import { Map, addProtocol, type ErrorEvent } from 'maplibre-gl'
import { Protocol } from 'pmtiles'
import 'maplibre-gl/dist/maplibre-gl.css'
import './style.css'
import { basemapStyle } from './lib/basemap'
import { searchControl } from './lib/search'
import drawMap from './map'

// Template wiring: the PMTiles protocol registration, the map instance, and
// the error surface. Do not edit this file — edit map.ts.

addProtocol('pmtiles', new Protocol().tile)

const map = new Map({
  container: 'map',
  style: basemapStyle(),
  attributionControl: false,
  // The artifact frame reports scrollHeight to size the iframe, so the map
  // takes its height from an aspect ratio in style.css rather than from the
  // viewport. dragRotate and touchPitch are off because a statistical map
  // has no reason to leave plan view.
  dragRotate: false,
})
map.touchZoomRotate.disableRotation()
map.addControl(searchControl(), 'top-left')

function showError(message: string): void {
  let element = document.querySelector('.artifact-error')
  if (!element) {
    element = document.createElement('div')
    element.className = 'artifact-error'
    document.body.prepend(element)
  }
  element.textContent = message
}

map.on('error', (event: ErrorEvent) =>
  showError(event.error?.message ?? 'Map error'),
)

// The renderer draws without a GPU, so tiles are still decoding and painting
// after the network goes quiet. index.html declares that this page says
// when it is done instead: once the data is drawn and the map has settled,
// or with the reason it could not draw.
window.artifactReady(
  new Promise<void>((resolve, reject) => {
    map.once('error', (event: ErrorEvent) => reject(event.error))
    map.on('load', () => {
      drawMap(map)
        .then(() => map.once('idle', () => resolve()))
        .catch((error: unknown) => {
          showError(error instanceof Error ? error.message : String(error))
          reject(error)
        })
    })
  }),
)
